pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 blockTime, uint256 senderSeed) public {
        vm.warp(blockTime);
        vm.deal(address(this), 10 ether);
        (bool success, ) = address(c).call{value: 10 ether}("");
        vm.warp(blockTime);
        vm.deal(address(this), 10 ether);
        (bool success2, ) = address(c).call{value: 10 ether}("");
        assertTrue(!success2);
    }
}
